// Strings: the key is the Serbian text, exactly as in the app's String Catalog (Localizable.xcstrings).
// src/i18n/strings.json and src/i18n/lang/*.json are generated by scripts/make_strings.mjs: every key used in the
// sources, with the app's translations verbatim when the app has the key, otherwise from src/i18n/web.json.
// Serbian ships in the main chunk; Cyrillic, English and Russian are loaded when chosen (before the first render at
// boot). Serbian Cyrillic ("sr-Cyrl") is the Serbian texts transliterated by the rules of evolako.rs: its catalog is
// generated (lang/sr-Cyrl.json), and the same function comes with it for the texts that are not in the catalog.
import { signal } from "@preact/signals";
import { contentLang, HTML_LANG, type ContentLang, type Lang } from "../lib/format";
import sr from "./lang/sr.json";

export { contentLang, HTML_LANG };
export type { ContentLang, Lang };
/** In the order of every language choice: Srpski (latinica), Српски (ћирилица), English, Русский. */
export const LANGS: Lang[] = ["sr", "sr-Cyrl", "en", "ru"];

/** The language as people read it in a list, the note next to it, and the short code of the public language button. */
export const LANG_NAMES: Record<Lang, string> = { sr: "Srpski", "sr-Cyrl": "Српски", en: "English", ru: "Русский" };
export const LANG_SCRIPTS: Partial<Record<Lang, string>> = { sr: "latinica", "sr-Cyrl": "ћирилица" };
export const LANG_CODES: Record<Lang, string> = { sr: "SR", "sr-Cyrl": "СР", en: "EN", ru: "RU" };

/** "Srpski (latinica)", "Српски (ћирилица)", "English", "Русский". */
export function langTitle(l: Lang): string {
  const script = LANG_SCRIPTS[l];
  return script ? `${LANG_NAMES[l]} (${script})` : LANG_NAMES[l];
}

type Plural = Partial<Record<"zero" | "one" | "two" | "few" | "many" | "other", string>>;
type Value = string | Plural;
type Dictionary = Record<string, Value>;

const dictionaries: Partial<Record<Lang, Dictionary>> = { sr: sr as unknown as Dictionary };
const loaders: Record<Exclude<Lang, "sr">, () => Promise<{ default: unknown }>> = {
  "sr-Cyrl": () => import("./lang/sr-Cyrl.json"),
  en: () => import("./lang/en.json"),
  ru: () => import("./lang/ru.json"),
};
const LANG_KEY = "evo.lang";

/** Serbian Latin → Cyrillic, there once Cyrillic was loaded. */
let toCyrillic: ((text: string) => string) | null = null;

/** Makes a language's strings available (a small cached chunk). */
export async function loadLang(l: Lang): Promise<void> {
  if (dictionaries[l] || l === "sr") return;
  if (l === "sr-Cyrl") {
    const [module, cyrillic] = await Promise.all([loaders[l](), import("./cyrillic.mjs")]);
    toCyrillic = cyrillic.cyrText;
    dictionaries[l] = module.default as Dictionary;
    return;
  }
  const module = await loaders[l]();
  dictionaries[l] = module.default as Dictionary;
}

function initialLang(): Lang {
  if (typeof document === "undefined") return "sr";
  const attr = (document.documentElement.getAttribute("lang") ?? "").toLowerCase();
  if (attr.startsWith("en")) return "en";
  if (attr.startsWith("ru")) return "ru";
  if (attr.startsWith("sr-cyrl")) return "sr-Cyrl";
  return "sr";
}

/** The interface language. boot.js already applied the saved choice or ?lang= to <html lang>. */
export const lang = signal<Lang>(initialLang());

export async function setLang(next: Lang): Promise<void> {
  try {
    await loadLang(next);
  } catch {
    return; // offline and not cached yet: keep the current language
  }
  lang.value = next;
  try {
    localStorage.setItem(LANG_KEY, next);
  } catch {
    // storage blocked: the choice lasts for this visit
  }
  document.documentElement.setAttribute("lang", HTML_LANG[next]);
}

const pluralRules = new Map<Lang, Intl.PluralRules>();
function pluralCategory(l: Lang, count: number): string {
  let rules = pluralRules.get(l);
  if (!rules) {
    rules = new Intl.PluralRules(HTML_LANG[l]);
    pluralRules.set(l, rules);
  }
  return rules.select(count);
}

/**
 * Fills %@, %lld, %d and positional %1$@ placeholders (String Catalog format). A Serbian long date ends with a
 * dot ("20. oktobar 2026."), so "…: %@." would read "2026.." — the sentence keeps one dot.
 */
export function fill(template: string, args: ReadonlyArray<string | number>): string {
  let next = 0;
  return template
    .replace(/%(?:(\d+)\$)?(@|lld|ld|d|%)/g, (_m, position: string | undefined, type: string) => {
      if (type === "%") return "%";
      const index = position ? Number(position) - 1 : next++;
      const value = args[index];
      return value === undefined ? "" : String(value);
    })
    .replace(/(\d)\.\./g, "$1.");
}

function resolve(key: string, l: Lang, count: number | null): string {
  const own = dictionaries[l]?.[key];
  const value = own ?? dictionaries.sr?.[key];
  if (value === undefined) {
    if (import.meta.env.DEV) console.warn(`[i18n] missing key: ${key}`);
    return key;
  }
  const category = count === null ? "other" : pluralCategory(l, count);
  const text = typeof value === "string" ? value : value[category as keyof Plural] ?? value.other ?? key;
  // A key the Cyrillic catalog does not have yet (an older cached chunk) is still shown in Cyrillic.
  return own === undefined ? inScript(text, l) : text;
}

/**
 * A Serbian text that is not in the catalog (the site content, an issue of Evolako pismo, a text of the server) in
 * the script of the language: Cyrillic for "sr-Cyrl", otherwise as it is. Not for what a person typed (names,
 * addresses, notes) and not for payment data.
 */
export function inScript(text: string, l: Lang = lang.value): string {
  return l === "sr-Cyrl" && toCyrillic ? toCyrillic(text) : text;
}

/** Translate in the current language (reading `lang` subscribes the component). */
export function t(key: string, ...args: Array<string | number>): string {
  return fill(resolve(key, lang.value, null), args);
}

/** Plural-aware: `count` selects the form and is also the first placeholder. */
export function tp(key: string, count: number, ...args: Array<string | number>): string {
  return fill(resolve(key, lang.value, count), [count, ...args]);
}

/** Translate in a given language (documents, e-mails) without subscribing to the current one. */
export function tIn(l: Lang, key: string, ...args: Array<string | number>): string {
  return fill(resolve(key, l, null), args);
}

/** Marks a key for extraction when it is stored as data and translated later with t(). */
export function msg<K extends string>(key: K): K {
  return key;
}

export function hasKey(key: string): boolean {
  return key in (dictionaries.sr ?? {});
}

/** A text of the site snapshot (faq.json, paketi.json): {sr, en, ru}; Cyrillic is the Serbian one, transliterated. */
export function siteText(text: Partial<Record<ContentLang, string>> | null | undefined): string {
  if (!text) return "";
  const l = lang.value;
  return inScript(text[contentLang(l)] ?? text.sr ?? "", l);
}

/** "kWh" / "кВт·ч" — units are translated, numbers stay Serbian. */
export function kWhUnit(): string {
  return t("kWh");
}

export function kWUnit(): string {
  return t("kW");
}
